import React from "react";
import './end.css';

interface EndScreenProps {
    Win: boolean;
    Lose: boolean;
    PlayAgain: () => void;
}

const End: React.FC<EndScreenProps> = ({ Win, Lose, PlayAgain }) => {
    const handleClick = () => {
        PlayAgain();
    }
    return(
        <>
            <div className="endcontainer">
                {Win && <div className="acontainer">You Won!
                <button className="playagain" onClick={handleClick}>Play Again?</button>    
                </div>}
                {Lose && <div className="acontainer">You Lost!
                <button className="playagain" onClick={handleClick}>Play Again?</button>    
                </div>}
            </div>
        </>
    );
}

export default End;
